from collections import defaultdict
class Solution:
    def maximumLength(self, nums: list[int], k: int) -> int:
        dp = [defaultdict(int) for _ in range(k + 1)]
        best = [0] * (k + 1)
        for x in nums:
            for j in range(k, -1, -1):
                v = dp[j][x] + 1
                if j > 0:
                    v = max(v, best[j - 1] + 1)
                dp[j][x] = v
                best[j] = max(best[j], v)
        return best[k]

