class Solution {
public:
    int maximumLength(vector<int>& nums, int k) {
        vector<unordered_map<int,int>> dp(k + 1);
        vector<int> best(k + 1, 0);
        for (int x : nums) {
            for (int j = k; j >= 0; j--) {
                int v = dp[j].count(x) ? dp[j][x] + 1 : 1;
                if (j > 0) v = max(v, best[j - 1] + 1);
                dp[j][x] = v;
                best[j] = max(best[j], v);
            }
        }
        return best[k];
    }
};

