class Solution {
    public int maximumLength(int[] nums, int k) {
        Map<Integer, Integer>[] dp = new HashMap[k + 1];
        for (int i = 0; i <= k; i++) dp[i] = new HashMap<>();
        int[] best = new int[k + 1];
        for (int x : nums) {
            for (int j = k; j >= 0; j--) {
                int v = dp[j].getOrDefault(x, 0) + 1;
                if (j > 0) v = Math.max(v, best[j - 1] + 1);
                dp[j].put(x, v);
                best[j] = Math.max(best[j], v);
            }
        }
        return best[k];
    }
}

