var maximumLength = function(nums, k) {
    const dp = Array.from({length: k + 1}, () => new Map());
    const best = new Array(k + 1).fill(0);
    for (const x of nums) {
        for (let j = k; j >= 0; j--) {
            let v = (dp[j].get(x) || 0) + 1;
            if (j > 0) v = Math.max(v, best[j - 1] + 1);
            dp[j].set(x, v);
            best[j] = Math.max(best[j], v);
        }
    }
    return best[k];
};
